import type { DeepReadonly } from "@btst/stack/plugins/api";

/** A newsletter subscriber. Secret management tokens are never included. */
export type Subscriber = {
	id: string;
	email: string;
	name?: string | null;
	status: "subscribed" | "unsubscribed" | "bounced";
	tags: string[];
	confirmedAt?: string | null;
	createdAt: string;
};

/** A campaign and its sending state. */
export type Campaign = {
	id: string;
	subject: string;
	fromName: string;
	fromEmail: string;
	replyTo?: string | null;
	body: string;
	format: "markdown" | "html";
	tags: string[];
	status: "draft" | "scheduled" | "sending" | "sent";
	scheduledAt?: string | null;
	sentAt?: string | null;
	createdAt: string;
	updatedAt: string;
};

/** Unique recipient counts; delivered means accepted by the configured adapter. */
export type CampaignStats = {
	recipientCount: number;
	delivered: number;
	opened: number;
	clicked: number;
	bounced: number;
	failed: number;
	openRate: number;
	clickRate: number;
};

/** Subscriber totals and daily cumulative subscription growth. */
export type SubscriberGrowth = {
	total: number;
	subscribed: number;
	unsubscribed: number;
	bounced: number;
	points: { date: string; count: number }[];
};

/** Lifecycle hooks run after input validation and operation authorization. */
export interface NewsletterPluginHooks {
	onBeforeSubscribe?: (
		email: string,
		context: { request?: Request },
	) => Promise<void> | void;
	onAfterSubscribe?: (
		subscriber: DeepReadonly<Subscriber>,
		context: { request?: Request },
	) => Promise<void> | void;
	onBeforeUnsubscribe?: (
		subscriber: DeepReadonly<Subscriber>,
		context: { request?: Request },
	) => Promise<void> | void;
	onAfterUnsubscribe?: (
		subscriber: DeepReadonly<Subscriber>,
		context: { request?: Request },
	) => Promise<void> | void;
	/** Send a confirmation message yourself instead of the default adapter message. */
	onConfirmationRequired?: (confirmation: {
		email: string;
		url: string;
	}) => Promise<void> | void;
	onAfterSend?: (
		campaign: DeepReadonly<Campaign>,
		context: { request?: Request },
	) => Promise<void> | void;
}

/** Internal database subscriber representation, including hashed bearer tokens. */
export interface SubscriberRecord
	extends Omit<Subscriber, "tags" | "confirmedAt" | "createdAt"> {
	tags: string;
	confirmedAt?: Date | null;
	createdAt: Date;
	confirmationToken?: string | null;
	confirmationExpiresAt?: Date | null;
	confirmationSentAt?: Date | null;
}

/** Internal database campaign representation. */
export interface CampaignRecord
	extends Omit<
		Campaign,
		"tags" | "scheduledAt" | "sentAt" | "createdAt" | "updatedAt"
	> {
	tags: string;
	scheduledAt?: Date | null;
	sentAt?: Date | null;
	createdAt: Date;
	updatedAt: Date;
}

/** Internal per-recipient delivery receipt. */
export interface SendRecord {
	id: string;
	key: string;
	campaignId: string;
	subscriberId: string;
	email: string;
	status: "pending" | "delivered" | "bounced" | "failed";
	trackingToken: string;
	unsubscribeToken: string;
	links: string;
	messageId?: string;
	sentAt?: Date | null;
	openedAt?: Date | null;
	clickedAt?: Date | null;
}

import { z } from "zod";

const header = z
	.string()
	.trim()
	.min(1)
	.max(500)
	.refine(
		(value) => !/[\r\n]/.test(value),
		"Email headers must not contain line breaks",
	);
export const subscriberStatusSchema = z.enum([
	"subscribed",
	"unsubscribed",
	"bounced",
]);
export const tagsSchema = z
	.array(z.string().trim().min(1).max(100))
	.max(50)
	.default([]);
export const emailSchema = z
	.email()
	.max(320)
	.transform((email) => email.trim().toLowerCase());
export const subscribeSchema = z.object({
	email: emailSchema,
	name: z.string().trim().max(200).optional(),
	tags: tagsSchema,
});
export const createSubscriberSchema = subscribeSchema.extend({
	status: subscriberStatusSchema.default("subscribed"),
});
export const updateSubscriberSchema = createSubscriberSchema.partial().extend({
	tags: tagsSchema.removeDefault().optional(),
	status: subscriberStatusSchema.optional(),
});
export const listSubscribersSchema = z.object({
	limit: z.coerce.number().int().min(1).max(200).default(50),
	offset: z.coerce.number().int().min(0).default(0),
	query: z.string().max(200).optional(),
	status: subscriberStatusSchema.optional(),
	tag: z.string().max(100).optional(),
});
export const listCampaignsSchema = z.object({
	limit: z.coerce.number().int().min(1).max(200).default(50),
	offset: z.coerce.number().int().min(0).default(0),
});
export const createCampaignSchema = z.object({
	subject: header,
	fromName: header.max(200),
	fromEmail: emailSchema,
	replyTo: emailSchema.optional(),
	body: z.string().min(1).max(1_000_000),
	format: z.enum(["markdown", "html"]).default("markdown"),
	tags: tagsSchema,
});
export const updateCampaignSchema = createCampaignSchema.partial().extend({
	replyTo: emailSchema.nullable().optional(),
	tags: tagsSchema.removeDefault().optional(),
	format: z.enum(["markdown", "html"]).optional(),
});
export const idSchema = z.object({ id: z.string().min(1).max(200) });
export const tokenSchema = z.object({
	token: z.string().regex(/^[a-f0-9]{64}$/),
});
export const scheduleCampaignSchema = z.object({
	scheduledAt: z.iso.datetime({ offset: true }),
});
export const testCampaignSchema = z.object({ email: emailSchema });
export const importSubscribersSchema = z.object({
	csv: z.string().min(1).max(2_000_000),
});
export const transactionalEmailSchema = z.object({
	to: emailSchema,
	subject: header,
	html: z.string().min(1).max(1_000_000),
	from: header,
	replyTo: emailSchema.optional(),
});

import { definePermissions, permission } from "@btst/stack/authorization";
import { z } from "zod";

const subscriberFacts = z.object({
	subscriberId: z.string(),
	status: z.enum(["subscribed", "unsubscribed", "bounced"]),
});
const campaignFacts = z.object({
	campaignId: z.string(),
	status: z.enum(["draft", "scheduled", "sending", "sent"]),
});
/** Browser-safe management permissions. Public bearer-token operations validate their own tokens. */
export const newsletterPermissions = definePermissions("newsletter", {
	subscriber: {
		read: permission(
			z.discriminatedUnion("scope", [
				z.object({ scope: z.literal("collection") }),
				z.object({ scope: z.literal("record"), subscriberId: z.string() }),
			]),
		),
		create: permission(),
		update: permission(subscriberFacts),
		delete: permission(subscriberFacts),
		import: permission(),
		export: permission(),
		subscribe: permission(),
		confirm: permission(),
		unsubscribe: permission(),
	},
	campaign: {
		read: permission(
			z.discriminatedUnion("scope", [
				z.object({ scope: z.literal("collection") }),
				z.object({ scope: z.literal("record"), campaignId: z.string() }),
			]),
		),
		create: permission(),
		update: permission(campaignFacts),
		delete: permission(campaignFacts),
		send: permission(campaignFacts),
		test: permission(campaignFacts),
		schedule: permission(campaignFacts),
	},
	analytics: { read: permission(), track: permission() },
	transactional: { send: permission() },
	scheduler: { run: permission() },
});

"use client";

import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";

export function NewsletterMarkdownPreview({ markdown }: { markdown: string }) {
	return (
		<div className="markdown-content">
			<div className="markdown-inner">
				<div className="markdown-body">
					<ReactMarkdown skipHtml remarkPlugins={[remarkGfm]}>
						{markdown}
					</ReactMarkdown>
				</div>
			</div>
		</div>
	);
}

"use client";

import { lazy } from "react";
import { ComposedRoute } from "@btst/stack/client/components";
import { newsletterPermissions } from "../../permissions";
import {
	NewsletterError,
	NewsletterLoading,
	NewsletterNotFound,
} from "./shared";

const Subscribers = lazy(() =>
	import("./pages/subscribers-page.internal").then((m) => ({
		default: m.SubscribersPage,
	})),
);
const Campaigns = lazy(() =>
	import("./pages/campaigns-page.internal").then((m) => ({
		default: m.CampaignsPage,
	})),
);
const Editor = lazy(() =>
	import("./pages/edit-campaign-page.internal").then((m) => ({
		default: m.EditCampaignPage,
	})),
);
const Stats = lazy(() =>
	import("./pages/campaign-stats-page.internal").then((m) => ({
		default: m.CampaignStatsPage,
	})),
);
const boundary = {
	ErrorComponent: NewsletterError,
	LoadingComponent: NewsletterLoading,
	NotFoundComponent: NewsletterNotFound,
	onError: (error: Error) => console.error("[btst/newsletter]", error),
};

export function SubscribersPageComponent() {
	return (
		<ComposedRoute
			{...boundary}
			path="/newsletter/subscribers"
			permission={newsletterPermissions.subscriber.read({
				scope: "collection",
			})}
			PageComponent={Subscribers}
		/>
	);
}
export function CampaignsPageComponent() {
	return (
		<ComposedRoute
			{...boundary}
			path="/newsletter/campaigns"
			permission={newsletterPermissions.campaign.read({ scope: "collection" })}
			PageComponent={Campaigns}
		/>
	);
}
export function EditCampaignPageComponent({ id }: { id?: string }) {
	return (
		<ComposedRoute
			{...boundary}
			path={id ? `/newsletter/campaigns/${id}` : "/newsletter/campaigns/new"}
			permission={
				id
					? newsletterPermissions.campaign.read({
							scope: "record",
							campaignId: id,
						})
					: newsletterPermissions.campaign.create()
			}
			PageComponent={Editor}
			props={{ id }}
		/>
	);
}
export function CampaignStatsPageComponent({ id }: { id: string }) {
	return (
		<ComposedRoute
			{...boundary}
			path={`/newsletter/campaigns/${id}/stats`}
			permission={newsletterPermissions.analytics.read()}
			PageComponent={Stats}
			props={{ id }}
		/>
	);
}

"use client";

import { useCampaign, useCampaignStats } from "@btst/stack/plugins/newsletter/client/hooks";
import { NewsletterPage, Status } from "../shared";

export function CampaignStatsPage({ id }: { id: string }) {
	const { data: campaign } = useCampaign(id);
	const { data: stats } = useCampaignStats(id);
	const metrics = [
		["Recipients", stats.recipientCount],
		["Delivered", stats.delivered],
		["Opened", stats.opened],
		["Clicked", stats.clicked],
		["Bounced", stats.bounced],
		["Failed", stats.failed],
	] as const;
	return (
		<NewsletterPage
			title={campaign.subject}
			description="Delivery and engagement for this campaign."
		>
			<div className="flex flex-wrap items-center gap-3">
				<Status value={campaign.status} />
				{campaign.sentAt && (
					<p className="text-sm text-muted-foreground">
						Sent {new Date(campaign.sentAt).toLocaleString()}
					</p>
				)}
			</div>
			<dl className="grid grid-cols-2 gap-x-8 gap-y-6 border-y py-6 sm:grid-cols-3 lg:grid-cols-6">
				{metrics.map(([label, value]) => (
					<div key={label} className="space-y-2">
						<dt className="text-sm text-muted-foreground">{label}</dt>
						<dd className="text-3xl font-semibold tabular-nums">
							{value.toLocaleString()}
						</dd>
					</div>
				))}
			</dl>
			<div className="grid gap-8 sm:grid-cols-2">
				{[
					["Open rate", stats.openRate],
					["Click rate", stats.clickRate],
				].map(([label, value]) => (
					<div className="space-y-3" key={label}>
						<div className="flex items-baseline justify-between gap-4">
							<h2 className="font-medium">{label}</h2>
							<p className="text-2xl font-semibold tabular-nums">
								{(Number(value) * 100).toFixed(1)}%
							</p>
						</div>
						<div
							className="h-2 overflow-hidden rounded-full bg-muted"
							aria-hidden="true"
						>
							<div
								className="h-full rounded-full bg-primary"
								style={{
									width: `${Math.max(0, Math.min(100, Number(value) * 100))}%`,
								}}
							/>
						</div>
					</div>
				))}
			</div>
			<p className="max-w-2xl text-sm text-muted-foreground">
				Delivered counts messages accepted by your email provider. Opens and
				clicks count unique recipients; email privacy settings and image
				blocking can affect open tracking.
			</p>
		</NewsletterPage>
	);
}

"use client";

import { useState } from "react";
import {
	PermissionAccess,
	usePluginOverrides,
	usePluginSiteNavigation,
} from "@btst/stack/context";
import { Button } from "@/components/ui/button";
import { useCampaigns } from "@btst/stack/plugins/newsletter/client/hooks";
import { newsletterPermissions } from "../../../permissions";
import { NEWSLETTER_PLUGIN_ID } from "../../constants";
import type { NewsletterPluginOverrides } from "../../overrides";
import { NewsletterPage, Pagination, Status } from "../shared";

export function CampaignsPage() {
	const [offset, setOffset] = useState(0);
	const { data } = useCampaigns({ limit: 25, offset });
	const { Link, resolve } = usePluginSiteNavigation(NEWSLETTER_PLUGIN_ID);
	const { localization } =
		usePluginOverrides<NewsletterPluginOverrides>(NEWSLETTER_PLUGIN_ID);
	return (
		<NewsletterPage
			title={localization?.title ?? "Newsletter"}
			description="Write to your subscribers. Follow each campaign from first draft to results."
			action={
				<PermissionAccess permission={newsletterPermissions.campaign.create()}>
					<Button asChild>
						<Link href={resolve("newsletter/campaigns/new").href}>
							{localization?.newCampaign ?? "New campaign"}
						</Link>
					</Button>
				</PermissionAccess>
			}
		>
			{data.items.length === 0 ? (
				<div className="space-y-3 py-10">
					<h2 className="text-xl font-medium">
						Your first newsletter starts here
					</h2>
					<p className="max-w-xl text-muted-foreground">
						Create a campaign, choose your audience, and send yourself a test
						before sharing it.
					</p>
				</div>
			) : (
				<div className="overflow-x-auto rounded-lg border">
					<table className="w-full min-w-[600px] text-left text-sm">
						<caption className="sr-only">Newsletter campaigns</caption>
						<thead className="border-b bg-muted/40">
							<tr>
								<th className="p-4 font-medium">Subject</th>
								<th className="p-4 font-medium">Status</th>
								<th className="p-4 font-medium">Audience</th>
								<th className="p-4 font-medium">Results</th>
							</tr>
						</thead>
						<tbody>
							{data.items.map((campaign) => (
								<tr key={campaign.id} className="border-b last:border-0">
									<td className="p-4">
										<Link
											className="font-medium underline-offset-4 hover:underline"
											href={resolve(`newsletter/campaigns/${campaign.id}`).href}
										>
											{campaign.subject}
										</Link>
										<p className="mt-1 text-xs text-muted-foreground">
											{campaign.fromName} &lt;{campaign.fromEmail}&gt;
										</p>
									</td>
									<td className="p-4">
										<Status value={campaign.status} />
										{campaign.scheduledAt && (
											<p className="mt-2 text-xs text-muted-foreground">
												{new Date(campaign.scheduledAt).toLocaleString()}
											</p>
										)}
									</td>
									<td className="p-4">
										{campaign.tags.length
											? campaign.tags.join(", ")
											: "All subscribers"}
									</td>
									<td className="p-4">
										<PermissionAccess
											permission={newsletterPermissions.analytics.read()}
										>
											<Link
												className="underline underline-offset-4"
												href={
													resolve(`newsletter/campaigns/${campaign.id}/stats`)
														.href
												}
											>
												View results
											</Link>
										</PermissionAccess>
									</td>
								</tr>
							))}
						</tbody>
					</table>
				</div>
			)}
			<Pagination offset={offset} total={data.total} onChange={setOffset} />
		</NewsletterPage>
	);
}

"use client";

import {
	useCallback,
	useEffect,
	useId,
	useRef,
	useState,
	type FormEvent,
} from "react";
import { PermissionRouteAccess } from "@btst/stack/client/components";
import {
	PermissionAccess,
	usePluginOverrides,
	usePluginSiteNavigation,
	useStack,
} from "@btst/stack/context";
import { MarkdownEditor } from "@btst/stack/components/markdown";
import { usePost } from "@btst/stack/plugins/blog/client/hooks";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import {
	AlertDialog,
	AlertDialogAction,
	AlertDialogCancel,
	AlertDialogContent,
	AlertDialogDescription,
	AlertDialogFooter,
	AlertDialogHeader,
	AlertDialogTitle,
	AlertDialogTrigger,
} from "@/components/ui/alert-dialog";
import { newsletterPermissions } from "../../../permissions";
import type { Campaign } from "../../../types";
import type { CampaignInput } from "@btst/stack/plugins/newsletter/api";
import {
	useCampaign,
	useCreateCampaign,
	useDeleteCampaign,
	useScheduleCampaign,
	useSendCampaign,
	useTestCampaign,
	useUpdateCampaign,
} from "@btst/stack/plugins/newsletter/client/hooks";
import type { NewsletterPluginOverrides } from "../../overrides";
import { NewsletterMarkdownPreview } from "../markdown-preview";
import { NEWSLETTER_PLUGIN_ID } from "../../constants";
import {
	Field,
	NewsletterLoading,
	NewsletterPage,
	Status,
	selectClass,
} from "../shared";

const emptyCampaign: CampaignInput = {
	subject: "",
	fromName: "",
	fromEmail: "",
	replyTo: "",
	body: "",
	format: "markdown",
	tags: [],
};

export function EditCampaignPage({ id }: { id?: string }) {
	return id ? (
		<ExistingCampaign id={id} />
	) : (
		<CampaignForm initial={emptyCampaign} />
	);
}

function ExistingCampaign({ id }: { id: string }) {
	const { data: campaign } = useCampaign(id);
	const initial = { ...campaign, replyTo: campaign.replyTo ?? undefined };
	return campaign.status === "draft" ? (
		<PermissionRouteAccess
			permission={newsletterPermissions.campaign.update({
				campaignId: id,
				status: campaign.status,
			})}
			LoadingComponent={NewsletterLoading}
		>
			<CampaignForm key={id} initial={initial} campaign={campaign} />
		</PermissionRouteAccess>
	) : (
		<CampaignForm key={id} initial={initial} campaign={campaign} />
	);
}

function BlogCampaignSource({
	slug,
	postId,
	onLoad,
}: {
	slug: string;
	postId: string;
	onLoad: (subject: string, body: string) => void;
}) {
	const { post, error, isLoading } = usePost(slug);
	const loaded = useRef(false);
	useEffect(() => {
		if (post && post.id === postId && !loaded.current) {
			loaded.current = true;
			onLoad(post.title, post.content);
		}
	}, [post, postId, onLoad]);
	if (error)
		return (
			<p role="alert" className="text-sm text-destructive">
				The blog post could not be loaded. Check your access or write a new
				campaign.
			</p>
		);
	if (isLoading)
		return (
			<p role="status" className="text-sm">
				Loading blog post…
			</p>
		);
	if (!post || post.id !== postId)
		return (
			<p role="alert" className="text-sm text-destructive">
				The selected blog post was not found.
			</p>
		);
	return (
		<p className="text-sm text-muted-foreground">
			Started from “{post.title}”. Changes here do not change the blog post.
		</p>
	);
}

function CampaignForm({
	initial,
	campaign,
}: {
	initial: CampaignInput;
	campaign?: Campaign;
}) {
	const id = useId();
	const { plugins } = useStack();
	const { Link, resolve, navigate } =
		usePluginSiteNavigation(NEWSLETTER_PLUGIN_ID);
	const { uploadImage } =
		usePluginOverrides<NewsletterPluginOverrides>(NEWSLETTER_PLUGIN_ID);
	const [values, setValues] = useState<CampaignInput>(initial);
	const [mode, setMode] = useState<"markdown" | "rich" | "preview">("markdown");
	const [source, setSource] = useState<{ slug: string; id: string }>();
	const [testEmail, setTestEmail] = useState("");
	const [scheduledAt, setScheduledAt] = useState("");
	const [message, setMessage] = useState("");
	const [error, setError] = useState("");
	const create = useCreateCampaign();
	const update = useUpdateCampaign();
	const send = useSendCampaign();
	const test = useTestCampaign();
	const schedule = useScheduleCampaign();
	const remove = useDeleteCampaign();
	const formRef = useRef<HTMLFormElement>(null);
	const pending =
		create.isPending ||
		update.isPending ||
		send.isPending ||
		test.isPending ||
		schedule.isPending ||
		remove.isPending;
	const readOnly = !!campaign && campaign.status !== "draft";
	const canDelete =
		campaign?.status === "draft" || campaign?.status === "scheduled";
	useEffect(() => {
		if (campaign) return;
		const params = new URLSearchParams(window.location.search);
		const slug = params.get("fromPostSlug");
		const postId = params.get("fromPostId");
		if (slug && postId) setSource({ slug, id: postId });
	}, [campaign]);
	const loadSource = useCallback(
		(subject: string, body: string) =>
			setValues((current) => ({ ...current, subject, body })),
		[],
	);
	const change = <K extends keyof CampaignInput>(
		key: K,
		value: CampaignInput[K],
	) => setValues((current) => ({ ...current, [key]: value }));
	const run = async (action: () => Promise<void>) => {
		setError("");
		setMessage("");
		try {
			await action();
		} catch (caught) {
			setError(
				caught instanceof Error
					? caught.message
					: "The campaign could not be updated. Try again.",
			);
		}
	};
	const save = async () => {
		if (!formRef.current?.reportValidity()) return;
		if (!values.body.trim())
			throw new Error("Write an email body before saving.");
		const data = {
			...values,
			replyTo: values.replyTo || undefined,
			tags: values.tags?.map((tag) => tag.trim()).filter(Boolean),
		};
		if (campaign) {
			await update.mutateAsync({
				id: campaign.id,
				data: { ...data, replyTo: values.replyTo || null },
			});
			return campaign.id;
		}
		const created = await create.mutateAsync(data);
		await navigate(`newsletter/campaigns/${created.id}`);
		return created.id;
	};
	const submit = (event: FormEvent<HTMLFormElement>) => {
		event.preventDefault();
		void run(async () => {
			await save();
			setMessage("Campaign saved");
		});
	};
	return (
		<NewsletterPage
			title={campaign ? campaign.subject : "New campaign"}
			description="A clear subject, a useful message, and the right audience."
			action={
				campaign && (
					<PermissionAccess permission={newsletterPermissions.analytics.read()}>
						<Button asChild variant="outline">
							<Link
								href={resolve(`newsletter/campaigns/${campaign.id}/stats`).href}
							>
								View results
							</Link>
						</Button>
					</PermissionAccess>
				)
			}
		>
			{source && plugins?.blog && (
				<BlogCampaignSource
					slug={source.slug}
					postId={source.id}
					onLoad={loadSource}
				/>
			)}
			{campaign && (
				<div className="flex flex-wrap items-center gap-3">
					<Status value={campaign.status} />
					{campaign.scheduledAt && (
						<p className="text-sm text-muted-foreground">
							Scheduled for {new Date(campaign.scheduledAt).toLocaleString()}
						</p>
					)}
					{readOnly && (
						<p className="text-sm text-muted-foreground">
							This campaign is {campaign.status}. Its content can no longer be
							edited.
						</p>
					)}
				</div>
			)}
			{message && (
				<p role="status" className="text-sm">
					{message}
				</p>
			)}
			{error && (
				<p role="alert" className="text-sm text-destructive">
					{error}
				</p>
			)}
			<form
				ref={formRef}
				onSubmit={submit}
				className="grid min-w-0 gap-8 lg:grid-cols-[minmax(0,2fr)_minmax(260px,1fr)]"
			>
				<div className="min-w-0 space-y-5">
					<Field id={`${id}-subject`} label="Subject">
						<Input
							id={`${id}-subject`}
							required
							maxLength={500}
							value={values.subject}
							readOnly={readOnly || pending}
							onChange={(e) => change("subject", e.target.value)}
							className="min-h-12 text-lg"
							placeholder="What should your readers know?"
						/>
					</Field>
					<div className="space-y-3">
						<div className="flex flex-wrap items-end justify-between gap-3">
							<label htmlFor={`${id}-body`} className="text-sm font-medium">
								Email body
							</label>
							<div
								className="flex flex-wrap gap-1"
								role="group"
								aria-label="Email editor mode"
								inert={pending}
							>
								<Button
									type="button"
									size="sm"
									variant={mode === "markdown" ? "secondary" : "ghost"}
									aria-pressed={mode === "markdown"}
									onClick={() => setMode("markdown")}
								>
									{values.format === "html" ? "HTML" : "Markdown"}
								</Button>
								{values.format !== "html" && !readOnly && (
									<Button
										type="button"
										size="sm"
										variant={mode === "rich" ? "secondary" : "ghost"}
										aria-pressed={mode === "rich"}
										onClick={() => setMode("rich")}
									>
										Rich text
									</Button>
								)}
								<Button
									type="button"
									size="sm"
									variant={mode === "preview" ? "secondary" : "ghost"}
									aria-pressed={mode === "preview"}
									onClick={() => setMode("preview")}
								>
									Preview
								</Button>
							</div>
						</div>
						{mode === "markdown" ? (
							<Textarea
								id={`${id}-body`}
								rows={20}
								value={values.body}
								readOnly={readOnly || pending}
								onChange={(e) => change("body", e.target.value)}
								placeholder="Write your newsletter…"
								className="min-h-[420px] resize-y leading-relaxed"
							/>
						) : mode === "rich" ? (
							<div
								className="min-h-[420px] rounded-lg border"
								role="group"
								aria-label="Email body rich text editor"
								inert={pending}
							>
								<MarkdownEditor
									value={values.body}
									onChange={(body) => change("body", body)}
									uploadImage={uploadImage}
								/>
							</div>
						) : (
							<div
								className="min-h-[420px] overflow-hidden rounded-lg border bg-background p-5"
								aria-label="Email preview"
							>
								{values.format === "html" ? (
									<iframe
										title="Email preview"
										sandbox=""
										srcDoc={values.body}
										className="h-[420px] w-full"
									/>
								) : (
									<NewsletterMarkdownPreview
										markdown={
											values.body || "Your email preview will appear here."
										}
									/>
								)}
								<p className="mt-8 border-t pt-4 text-xs text-muted-foreground">
									An unsubscribe link is added automatically to each
									subscriber's email.
								</p>
							</div>
						)}
					</div>
				</div>
				<aside className="min-w-0 space-y-6">
					<fieldset disabled={readOnly || pending} className="space-y-4">
						<legend className="mb-4 text-lg font-medium">
							Sender and audience
						</legend>
						<Field id={`${id}-from-name`} label="From name">
							<Input
								id={`${id}-from-name`}
								required
								maxLength={200}
								value={values.fromName}
								onChange={(e) => change("fromName", e.target.value)}
							/>
						</Field>
						<Field id={`${id}-from-email`} label="From email">
							<Input
								id={`${id}-from-email`}
								required
								type="email"
								value={values.fromEmail}
								onChange={(e) => change("fromEmail", e.target.value)}
							/>
						</Field>
						<Field id={`${id}-reply-to`} label="Reply-to">
							<Input
								id={`${id}-reply-to`}
								type="email"
								value={values.replyTo ?? ""}
								onChange={(e) => change("replyTo", e.target.value)}
							/>
						</Field>
						<Field
							id={`${id}-tags`}
							label="Audience tags"
							hint="Leave empty to reach all subscribed readers. Separate tags with commas; readers matching any tag are included."
						>
							<Input
								id={`${id}-tags`}
								value={values.tags?.join(", ") ?? ""}
								onChange={(e) =>
									change(
										"tags",
										e.target.value.split(",").map((tag) => tag.trim()),
									)
								}
								onBlur={() => change("tags", values.tags?.filter(Boolean))}
							/>
						</Field>
						<Field id={`${id}-format`} label="Body format">
							<select
								id={`${id}-format`}
								className={selectClass}
								value={values.format ?? "markdown"}
								onChange={(e) => {
									change("format", e.target.value as "markdown" | "html");
									setMode("markdown");
								}}
							>
								<option value="markdown">Markdown</option>
								<option value="html">HTML</option>
							</select>
						</Field>
					</fieldset>
					{!readOnly && (
						<Button className="w-full" type="submit" disabled={pending}>
							{pending ? "Saving…" : "Save draft"}
						</Button>
					)}
				</aside>
			</form>
			{campaign && !readOnly && (
				<section
					aria-label="Campaign delivery"
					className="grid gap-6 border-t pt-8 md:grid-cols-3"
				>
					<div className="space-y-3">
						<h2 className="text-lg font-medium">Send a test</h2>
						<Field id={`${id}-test`} label="Test email address">
							<Input
								id={`${id}-test`}
								type="email"
								value={testEmail}
								onChange={(e) => setTestEmail(e.target.value)}
							/>
						</Field>
						<PermissionAccess
							permission={newsletterPermissions.campaign.test({
								campaignId: campaign.id,
								status: campaign.status,
							})}
						>
							<Button
								variant="outline"
								disabled={pending || !testEmail}
								onClick={() =>
									void run(async () => {
										const saved = await save();
										if (!saved) return;
										await test.mutateAsync({ id: saved, email: testEmail });
										setMessage("Test email sent");
									})
								}
							>
								Send test email
							</Button>
						</PermissionAccess>
					</div>
					<div className="space-y-3">
						<h2 className="text-lg font-medium">Schedule delivery</h2>
						<Field
							id={`${id}-schedule`}
							label="Scheduled send time"
							hint="Uses your local time zone."
						>
							<Input
								id={`${id}-schedule`}
								type="datetime-local"
								value={scheduledAt}
								onChange={(e) => setScheduledAt(e.target.value)}
							/>
						</Field>
						<PermissionAccess
							permission={newsletterPermissions.campaign.schedule({
								campaignId: campaign.id,
								status: campaign.status,
							})}
						>
							<Button
								variant="outline"
								disabled={pending || !scheduledAt}
								onClick={() =>
									void run(async () => {
										const date = new Date(scheduledAt);
										if (
											!Number.isFinite(date.getTime()) ||
											date.getTime() <= Date.now()
										)
											throw new Error(
												"Choose a scheduled send time in the future.",
											);
										const saved = await save();
										if (!saved) return;
										await schedule.mutateAsync({
											id: saved,
											scheduledAt: date.toISOString(),
										});
										setMessage("Campaign scheduled");
									})
								}
							>
								Schedule campaign
							</Button>
						</PermissionAccess>
					</div>
					<div className="space-y-3">
						<h2 className="text-lg font-medium">Ready to send?</h2>
						<p className="text-sm text-muted-foreground">
							Only subscribed, confirmed readers in your audience receive this
							email.
						</p>
						<PermissionAccess
							permission={newsletterPermissions.campaign.send({
								campaignId: campaign.id,
								status: campaign.status,
							})}
						>
							<AlertDialog>
								<AlertDialogTrigger asChild>
									<Button disabled={pending}>Send campaign</Button>
								</AlertDialogTrigger>
								<AlertDialogContent>
									<AlertDialogHeader>
										<AlertDialogTitle>Send this campaign now?</AlertDialogTitle>
										<AlertDialogDescription>
											This sends your message to all eligible subscribers
											{values.tags?.filter(Boolean).length
												? ` matching ${values.tags.filter(Boolean).join(", ")}`
												: ""}
											. Sent emails cannot be recalled.
										</AlertDialogDescription>
									</AlertDialogHeader>
									<AlertDialogFooter>
										<AlertDialogCancel>Cancel</AlertDialogCancel>
										<AlertDialogAction
											onClick={() =>
												void run(async () => {
													const saved = await save();
													if (!saved) return;
													await send.mutateAsync(saved);
													setMessage("Campaign sent");
												})
											}
										>
											Send now
										</AlertDialogAction>
									</AlertDialogFooter>
								</AlertDialogContent>
							</AlertDialog>
						</PermissionAccess>
					</div>
				</section>
			)}
			{campaign && canDelete && (
				<div className="border-t pt-6">
					<PermissionAccess
						permission={newsletterPermissions.campaign.delete({
							campaignId: campaign.id,
							status: campaign.status,
						})}
					>
						<AlertDialog>
							<AlertDialogTrigger asChild>
								<Button variant="outline" disabled={pending}>
									{campaign.status === "scheduled"
										? "Delete scheduled campaign"
										: "Delete draft"}
								</Button>
							</AlertDialogTrigger>
							<AlertDialogContent>
								<AlertDialogHeader>
									<AlertDialogTitle>
										{campaign.status === "scheduled"
											? "Delete scheduled campaign?"
											: "Delete campaign draft?"}
									</AlertDialogTitle>
									<AlertDialogDescription>
										“{campaign.subject}” and its content will be removed.
										{campaign.status === "scheduled" &&
											" Deleting this campaign cancels its scheduled delivery."}
									</AlertDialogDescription>
								</AlertDialogHeader>
								<AlertDialogFooter>
									<AlertDialogCancel>Cancel</AlertDialogCancel>
									<AlertDialogAction
										onClick={() =>
											void run(async () => {
												await remove.mutateAsync(campaign.id);
												await navigate("newsletter/campaigns");
											})
										}
									>
										Delete campaign
									</AlertDialogAction>
								</AlertDialogFooter>
							</AlertDialogContent>
						</AlertDialog>
					</PermissionAccess>
				</div>
			)}
		</NewsletterPage>
	);
}

"use client";

import { useEffect, useId, useRef, useState, type FormEvent } from "react";
import { PermissionAccess, usePluginOverrides } from "@btst/stack/context";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import {
	AlertDialog,
	AlertDialogAction,
	AlertDialogCancel,
	AlertDialogContent,
	AlertDialogDescription,
	AlertDialogFooter,
	AlertDialogHeader,
	AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import {
	useSubscribers,
	useCreateSubscriber,
	useUpdateSubscriber,
	useDeleteSubscriber,
	useImportSubscribers,
	useSubscriberExport,
	useSubscriberGrowth,
} from "@btst/stack/plugins/newsletter/client/hooks";
import { newsletterPermissions } from "../../../permissions";
import { NEWSLETTER_PLUGIN_ID } from "../../constants";
import type { NewsletterPluginOverrides } from "../../overrides";
import type { Subscriber, SubscriberGrowth } from "../../../types";
import type { SubscriberInput } from "@btst/stack/plugins/newsletter/api";
import {
	Field,
	NewsletterPage,
	Pagination,
	Status,
	selectClass,
} from "../shared";

export function SubscribersPage() {
	const id = useId();
	const [query, setQuery] = useState("");
	const [status, setStatus] = useState("");
	const [tag, setTag] = useState("");
	const [offset, setOffset] = useState(0);
	const [editing, setEditing] = useState<Subscriber | null | undefined>();
	const [deleting, setDeleting] = useState<Subscriber>();
	const [importing, setImporting] = useState(false);
	const [message, setMessage] = useState("");
	const [error, setError] = useState("");
	const { data } = useSubscribers({
		query: query || undefined,
		status: status || undefined,
		tag: tag || undefined,
		offset,
		limit: 25,
	});
	const formRef = useRef<HTMLFormElement>(null);
	useEffect(() => {
		if (editing !== undefined)
			formRef.current?.querySelector<HTMLInputElement>("input")?.focus();
	}, [editing]);
	const create = useCreateSubscriber();
	const update = useUpdateSubscriber();
	const remove = useDeleteSubscriber();
	const importCSV = useImportSubscribers();
	const exportCSV = useSubscriberExport();
	const { localization } =
		usePluginOverrides<NewsletterPluginOverrides>(NEWSLETTER_PLUGIN_ID);
	const pending =
		create.isPending ||
		update.isPending ||
		remove.isPending ||
		importCSV.isPending ||
		exportCSV.isFetching;
	const run = async (action: () => Promise<void>) => {
		setError("");
		setMessage("");
		try {
			await action();
		} catch (caught) {
			setError(
				caught instanceof Error
					? caught.message
					: "The subscriber change failed. Try again.",
			);
		}
	};
	const save = (event: FormEvent<HTMLFormElement>) => {
		event.preventDefault();
		const fields = new FormData(event.currentTarget);
		const input: SubscriberInput = {
			email: String(fields.get("email")),
			name: String(fields.get("name") || ""),
			tags: String(fields.get("tags") || "")
				.split(",")
				.map((tag) => tag.trim())
				.filter(Boolean),
			status: String(fields.get("status")) as SubscriberInput["status"],
		};
		void run(async () => {
			if (editing) await update.mutateAsync({ id: editing.id, data: input });
			else await create.mutateAsync(input);
			setEditing(undefined);
			setMessage("Subscriber saved");
		});
	};
	return (
		<NewsletterPage
			title={localization?.subscribers ?? "Subscribers"}
			description="Keep your audience up to date. Target a campaign with the tags you assign here."
			action={
				<PermissionAccess
					permission={newsletterPermissions.subscriber.create()}
				>
					<Button
						onClick={() => {
							setEditing(null);
							setImporting(false);
						}}
					>
						Add subscriber
					</Button>
				</PermissionAccess>
			}
		>
			<PermissionAccess permission={newsletterPermissions.analytics.read()}>
				<SubscriberGrowthSection />
			</PermissionAccess>
			<div className="flex flex-wrap gap-3">
				<PermissionAccess
					permission={newsletterPermissions.subscriber.import()}
				>
					<Button
						variant="outline"
						disabled={pending}
						onClick={() => {
							setImporting(!importing);
							setEditing(undefined);
						}}
					>
						Import CSV
					</Button>
				</PermissionAccess>
				<PermissionAccess
					permission={newsletterPermissions.subscriber.export()}
				>
					<Button
						variant="outline"
						disabled={pending}
						onClick={() =>
							void run(async () => {
								const result = await exportCSV.refetch();
								if (result.error) throw result.error;
								const csv = result.data?.csv;
								if (csv === undefined)
									throw new Error("CSV could not be exported. Try again.");
								const url = URL.createObjectURL(
									new Blob([csv], { type: "text/csv;charset=utf-8" }),
								);
								const anchor = document.createElement("a");
								anchor.href = url;
								anchor.download = "subscribers.csv";
								anchor.click();
								URL.revokeObjectURL(url);
								setMessage("Subscribers exported");
							})
						}
					>
						Export CSV
					</Button>
				</PermissionAccess>
			</div>
			{error && (
				<p role="alert" className="text-sm text-destructive">
					{error}
				</p>
			)}
			{message && (
				<p role="status" className="text-sm">
					{message}
				</p>
			)}
			{editing !== undefined && (
				<form
					ref={formRef}
					key={editing?.id ?? "new"}
					className="space-y-5 rounded-lg border p-5"
					onSubmit={save}
				>
					<h2 className="text-xl font-medium">
						{editing ? "Edit subscriber" : "Add subscriber"}
					</h2>
					<div className="grid gap-4 sm:grid-cols-2">
						<Field id={`${id}-email`} label="Email">
							<Input
								id={`${id}-email`}
								name="email"
								type="email"
								required
								maxLength={254}
								defaultValue={editing?.email}
							/>
						</Field>
						<Field id={`${id}-name`} label="Name">
							<Input
								id={`${id}-name`}
								name="name"
								maxLength={200}
								defaultValue={editing?.name ?? ""}
							/>
						</Field>
						<Field
							id={`${id}-tags`}
							label="Tags"
							hint="Separate tags with commas."
						>
							<Input
								id={`${id}-tags`}
								name="tags"
								defaultValue={editing?.tags.join(", ")}
							/>
						</Field>
						<Field id={`${id}-status`} label="Status">
							<select
								id={`${id}-status`}
								name="status"
								className={selectClass}
								defaultValue={editing?.status ?? "subscribed"}
							>
								<option value="subscribed">Subscribed</option>
								<option value="unsubscribed">Unsubscribed</option>
								<option value="bounced">Bounced</option>
							</select>
						</Field>
					</div>
					<div className="flex gap-3">
						<Button type="submit" disabled={pending}>
							Save subscriber
						</Button>
						<Button
							type="button"
							variant="outline"
							onClick={() => setEditing(undefined)}
						>
							Cancel
						</Button>
					</div>
				</form>
			)}
			{importing && (
				<form
					className="space-y-4 rounded-lg border p-5"
					onSubmit={(event) => {
						event.preventDefault();
						const csv = String(new FormData(event.currentTarget).get("csv"));
						void run(async () => {
							const result = await importCSV.mutateAsync(csv);
							setMessage(`${result.imported} subscribers imported`);
							setImporting(false);
						});
					}}
				>
					<Field
						id={`${id}-csv`}
						label="CSV data"
						hint="Use email, name, status and tags columns. Tags are a JSON array in a quoted CSV cell."
					>
						<Textarea
							id={`${id}-csv`}
							name="csv"
							rows={6}
							required
							placeholder={
								"email,name,status,tags\nreader@example.com,Alex,subscribed,"
							}
						/>
					</Field>
					<Button type="submit" disabled={pending}>
						Import subscribers
					</Button>
				</form>
			)}
			<div className="grid gap-4 sm:grid-cols-3">
				<Field id={`${id}-search`} label="Search subscribers">
					<Input
						id={`${id}-search`}
						type="search"
						value={query}
						onChange={(e) => {
							setQuery(e.target.value);
							setOffset(0);
						}}
						placeholder="Email or name"
					/>
				</Field>
				<Field id={`${id}-filter-status`} label="Filter by status">
					<select
						id={`${id}-filter-status`}
						className={selectClass}
						value={status}
						onChange={(e) => {
							setStatus(e.target.value);
							setOffset(0);
						}}
					>
						<option value="">All statuses</option>
						<option value="subscribed">Subscribed</option>
						<option value="unsubscribed">Unsubscribed</option>
						<option value="bounced">Bounced</option>
					</select>
				</Field>
				<Field id={`${id}-filter-tag`} label="Filter by tag">
					<Input
						id={`${id}-filter-tag`}
						value={tag}
						onChange={(e) => {
							setTag(e.target.value);
							setOffset(0);
						}}
						placeholder="Any tag"
					/>
				</Field>
			</div>
			{data.items.length === 0 ? (
				<p className="py-8 text-muted-foreground">
					No subscribers match. Add a subscriber or adjust your filters.
				</p>
			) : (
				<div className="overflow-x-auto rounded-lg border">
					<table className="w-full min-w-[650px] text-left text-sm">
						<caption className="sr-only">Newsletter subscribers</caption>
						<thead className="border-b bg-muted/40">
							<tr>
								<th className="p-4 font-medium">Email</th>
								<th className="p-4 font-medium">Status</th>
								<th className="p-4 font-medium">Tags</th>
								<th className="p-4 font-medium">Actions</th>
							</tr>
						</thead>
						<tbody>
							{data.items.map((subscriber) => (
								<tr className="border-b last:border-0" key={subscriber.id}>
									<td className="p-4">
										{subscriber.email}
										{subscriber.name && (
											<p className="mt-1 text-xs text-muted-foreground">
												{subscriber.name}
											</p>
										)}
									</td>
									<td className="p-4">
										<Status value={subscriber.status} />
									</td>
									<td className="p-4">{subscriber.tags.join(", ") || "—"}</td>
									<td className="p-4">
										<div className="flex gap-2">
											<PermissionAccess
												permission={newsletterPermissions.subscriber.update({
													subscriberId: subscriber.id,
													status: subscriber.status,
												})}
											>
												<Button
													size="sm"
													className="min-h-11"
													variant="outline"
													aria-label={`Edit ${subscriber.email}`}
													onClick={() => {
														setEditing(subscriber);
														setImporting(false);
													}}
												>
													Edit
												</Button>
											</PermissionAccess>
											<PermissionAccess
												permission={newsletterPermissions.subscriber.delete({
													subscriberId: subscriber.id,
													status: subscriber.status,
												})}
											>
												<Button
													size="sm"
													className="min-h-11"
													variant="outline"
													aria-label={`Delete ${subscriber.email}`}
													disabled={pending}
													onClick={() => setDeleting(subscriber)}
												>
													Delete
												</Button>
											</PermissionAccess>
										</div>
									</td>
								</tr>
							))}
						</tbody>
					</table>
				</div>
			)}
			<Pagination offset={offset} total={data.total} onChange={setOffset} />
			<AlertDialog
				open={!!deleting}
				onOpenChange={(open) => {
					if (!open) setDeleting(undefined);
				}}
			>
				<AlertDialogContent>
					<AlertDialogHeader>
						<AlertDialogTitle>Delete subscriber?</AlertDialogTitle>
						<AlertDialogDescription>
							{deleting?.email} will be removed from your subscriber list.
						</AlertDialogDescription>
					</AlertDialogHeader>
					<AlertDialogFooter>
						<AlertDialogCancel>Cancel</AlertDialogCancel>
						<AlertDialogAction
							onClick={() => {
								const subscriber = deleting;
								if (subscriber)
									void run(async () => {
										await remove.mutateAsync(subscriber.id);
										setMessage("Subscriber deleted");
										if (data.items.length === 1 && offset > 0)
											setOffset(offset - 25);
									});
							}}
						>
							Delete subscriber
						</AlertDialogAction>
					</AlertDialogFooter>
				</AlertDialogContent>
			</AlertDialog>
		</NewsletterPage>
	);
}

function SubscriberGrowthSection() {
	const { data: growth } = useSubscriberGrowth();
	return <SubscriberGrowthChart growth={growth} />;
}

function SubscriberGrowthChart({ growth }: { growth: SubscriberGrowth }) {
	const max = Math.max(1, ...growth.points.map((point) => point.count));
	const points = growth.points
		.map(
			(point, index) =>
				`${growth.points.length === 1 ? 300 : 20 + (index / (growth.points.length - 1)) * 560},${130 - (point.count / max) * 110}`,
		)
		.join(" ");
	return (
		<section
			aria-labelledby="newsletter-growth-title"
			className="grid gap-6 border-b pb-6 sm:grid-cols-[1fr_2fr]"
		>
			<div className="space-y-3">
				<h2 id="newsletter-growth-title" className="text-lg font-medium">
					Subscriber growth
				</h2>
				<p className="text-3xl font-semibold tabular-nums">
					{growth.total.toLocaleString()}{" "}
					<span className="text-base font-normal text-muted-foreground">
						total subscribers
					</span>
				</p>
				<p className="text-sm text-muted-foreground">
					{growth.subscribed} subscribed, {growth.unsubscribed} unsubscribed,{" "}
					{growth.bounced} bounced
				</p>
			</div>
			<div className="min-w-0">
				{growth.points.length ? (
					<>
						<svg
							viewBox="0 0 600 150"
							role="img"
							aria-label="Cumulative subscribers over time"
							className="h-32 w-full text-primary"
						>
							<title>Cumulative subscribers over time</title>
							<line
								x1="20"
								y1="130"
								x2="580"
								y2="130"
								stroke="currentColor"
								opacity="0.2"
							/>
							<polyline
								points={points}
								fill="none"
								stroke="currentColor"
								strokeWidth="3"
							/>
							{growth.points.length === 1 && (
								<circle
									cx="300"
									cy={130 - (growth.points[0]!.count / max) * 110}
									r="4"
									fill="currentColor"
								/>
							)}
						</svg>
						<div className="flex justify-between gap-4 text-xs text-muted-foreground">
							<span>{growth.points[0]?.date}</span>
							<span>{growth.points.at(-1)?.date}</span>
						</div>
						<details className="mt-2 text-xs text-muted-foreground">
							<summary className="cursor-pointer">View growth data</summary>
							<ul className="mt-2 space-y-1">
								{growth.points.map((point) => (
									<li key={point.date}>
										{point.date}: {point.count} subscribers
									</li>
								))}
							</ul>
						</details>
					</>
				) : (
					<p className="py-8 text-sm text-muted-foreground">
						Growth appears after your first subscriber joins.
					</p>
				)}
			</div>
		</section>
	);
}

